Record E2F (i : nat) (c : CC.cutpoint) (E1 E2 : env) (gx : nat) (ps3 : PML.pstate) (code d1 : Z) : Prop := MKE2F {
  e2_fix : forall k z, (k < 40)%nat -> bv_unsigned (ev E0 k) = z -> CL5A.uv E2 (EVar k) = z;
  e2_ag : forall e, APC.expr_vars_lt (CC.cp_nx c) e = true -> CL5A.uv E2 e = CL5A.uv E1 e;
  e2_46 : CL5A.uv E2 (EVar 46) = CL5A.uv E1 (EVar JV);
  e2_g : forall k v, (k < 14)%nat -> nth k (ghv ps3 code d1) 0 = v -> 0 <= v < 2 ^ 64 -> CL5A.uv E2 (EVar (gx + k)) = v }.
